# -*- coding: utf-8 -*-
# Sixth pass (Sam, 21 Sep 2026): the fiscal specification alone is quoted in the text;
# the trend counterparts live in Table 2 and Online Appendix Table B3.
S = lambda n: "Section §§" + n + "§§"

E2 = ("where mₜ is non-EU inflows per thousand lagged working-age residents, Δ̂dₜ(10) the projected "
      "ten-year OADR change from the current vintage, τₜ₋₁ the lagged tax take per working-age person, "
      "Δln Bₜ₋₁ the lagged log change in the debt-to-GDP ratio and uₜ₋₁ the lagged "
      "unemployment rate. The log-level form, favoured by specification tests (Section 6.1), implies that a given "
      "projected deterioration calls forth a given percentage adjustment; the lagged dependent variable captures the "
      "model's adjustment costs and the persistence documented in the UK literature (Mitchell and Pain, 2003; Hatton, "
      "2005). A second specification replaces τₜ₋₁ with a trend; the two are collinear (r = 0.98), so "
      "both are reported in Table 2 and the fiscal specification is carried through the rest of the paper. Inference uses HAC standard errors, "
      "with Newey–West and OLS errors in Online Appendix Table B2.")
IC1 = ("*Zero-net-migration projections.* From each vintage's published components of change, the projected OADR at "
       "every horizon is recomputed under zero net migration from the observation year forward, by removing the "
       "vintage's cumulative assumed net migration from the projected working-age denominator (Online Appendix A), so "
       "that the regressor cannot contain the vintages' migration assumptions. It returns 0.0075 (HAC s.e. 0.0013) "
       "against 0.0082 with the published projections, with unchanged significance, comparable or cleaner diagnostics, and an implied long-run response of "
       "1.5 per cent. The response of controlled migration to projected ageing is not an artefact of the projections' "
       "own migration assumptions.")
IC2 = ("*Publication dating.* Dating each vintage from the year after its base reassigns the vintage in force in 21 of "
       "the 41 years, moving one observation by more than fifteen points. The estimate barely moves: 0.0086 (HAC s.e. "
       "0.0015) against 0.0082, significant at 0.1 per cent with diagnostics passing; the zero-migration variant returns 0.0072 (0.0015), the total dependency ratio falls to "
       "−0.0002 (p = 0.87) and the EU placebo stays insignificant (p = 0.35).")
IC3 = ("*The projection's marginal contribution.* With a lagged dependent variable, adjusted R² reaches 0.94 before "
       "the projection enters, so the informative comparison is the nested one. Dropping the projection gives F(1, 35) = "
       "19.07 (p = 0.0001), with the information criterion improving by 15.8 points when it is restored, a "
       "difference conventionally taken to leave no support for the restricted model; and without the projection "
       "RESET falls to p = 0.099 against p = 0.63 with it, rejecting outright in the trend specification (p = 0.045 "
       "against 0.22). The omission does not merely cost fit; it leaves detectable "
       "misspecification.")
F1 = ("*Old-age versus total dependency.* If the mechanism is fiscal, the projection that matters is the old-age ratio, "
      "since pensioners are expensive, not the total ratio, whose child component is cheap (" + S("4.2") + "). "
      "Substituting the projected ten-year change in the total dependency ratio eliminates the result: the coefficient "
      "falls to 0.0015 (p = 0.25) and is indistinguishable from zero, as it is in every other variant, at every horizon, in levels as in deltas. Against the no-projection "
      "baseline the contrast is sharper still: the old-age ratio improves the information criterion by 15.8 points, "
      "the total ratio worsens it by 0.8 (F(1, 35) = 1.03, p = 0.32), so the model is better "
      "specified with no projection than with the wrong one. A generic demographic confounder has no reason to select "
      "the pensioner-specific ratio so cleanly; a fiscal mechanism must.")
F2 = ("*The uncontrolled margin.* Might some unobserved driver, rising UK attractiveness, labour demand, or networks, "
      "correlate with projected ageing and move all migration, with policy irrelevant? EU inflows provide the test, "
      "responding freely to every such driver but not to UK entry policy. Re-estimating the full specification on EU "
      "inflows, constructed identically, returns an OADR-projection coefficient of 0.0028 (p = 0.42); only the persistence term survives. Figure 2 shows the "
      "contrast as added-variable plots in which the fitted slope is the coefficient: a clear conditional relationship "
      "on the controlled margin, none on the uncontrolled one. Whatever moved non-EU inflows in step with projected "
      "ageing did not move the flows the government could not ration; the confound would have to operate exclusively "
      "on the controlled margin, which is to say it would have to *be* policy.")
PE = ("Mitchell, Pain and Riley (2011) attribute the post-1997 expansion to a liberal policy era, captured by a step "
      "indicator from 1998, which their 2007 sample end makes indistinguishable from a 1998–2007 window. Adding their "
      "full indicator set (POL97, POL02 for the 2002 skilled-worker route, and enlargement indicators for 1986, 1995 and "
      "2004) to the fiscal specification leaves the indicators jointly irrelevant under HAC inference (F(5, 30) = 1.23, "
      "p = 0.32), while the projection holds at 0.0078 (p < 0.001). The "
      "reason is that the indicator nearly discretises the projection: the ten-year delta averages 0.9 points before "
      "1998, 14.9 within the window and −4.5 after 2007, so the literature's dummies were standing in for the "
      "projections. Two checks confirm the reading. Interacting the step with the projection returns a negative "
      "interaction (−0.0068, p = 0.37), the opposite of what a post-1997 account requires; and in Mitchell, Pain and "
      "Riley's own differenced form the projection is the only variable that registers (0.0062, p = 0.099 for non-EU "
      "inflows; 0.0072, p = 0.033 for total inflows), while the indicators return p = 0.68, 0.79 and 0.71. Where the "
      "indicators do earn their place is on total inflows including the EU margin the government could not ration "
      "(F(5, 30) = 5.10, p = 0.002), with the projection falling to 0.0028 (p = 0.30), the EU placebo arriving from the "
      "other direction, reported with the caveat that this specification reaches a maximum VIF of 62 (Online Appendix B).")
FR = ("The remaining checks, and every check in the trend specification, are in Online Appendix B. The result does not depend on the per-capita scaling: on "
      "gross non-EU inflows the coefficient is 0.0080 (HAC s.e. 0.0014), and in levels each further projected point is associated with roughly 1,300 to 1,400 additional "
      "arrivals a year. On the LTIM series from 1991 it remains significant at five per cent (0.0103, s.e. 0.0038, N = "
      "28). The projected level in place of the change gives 0.0082; the term is significant at three, five, seven, and "
      "ten years, with ten fitting best, and the one-year change alone carries no signal (p = 0.56). Starting the sample "
      "in 1983 or 1987 returns 0.0087 and 0.0082, both significant at 0.1 per cent. What the battery cannot exclude is "
      "a confounder sharing the projection's exact profile, fiscal, pensioner-specific, operative only on the controlled "
      "margin, and timed to the vintages; none has suggested itself, and closing that residual vulnerability is what "
      "the agenda of " + S("7") + " is built for.")
